#include "stm32l4xx.h"
#define SYSTEM_RUN 0x00
static uint8_t g_state = SYSTEM_RUN;

void LowPower_EnterSTOP(void) {
    HAL_NVIC_DisableIRQ(RTC_IRQn);
    HalPeripheral_PreSleep();
    HAL_PWREGEx_SetVoltageRange(PWR_REGULATOR_VOLTAGE_RANGE_2);
    HAL_PWR_EnterSTOPMode(PWR_LOWPOWER_RESET_UV, PWR_STOPEntry_WFI);
    HAL_PWREGEx_SetVoltageRange(PWR_REGULATOR_VOLTAGE_RANGE_1);
    HalPeripheral_PostWake();
}

uint8_t LowPower_GetResetReason(void) {
    if (PWR->PRRF & PWR_PRRF_RFQF) return 1;
    if (PWR->PRRF & PWR_PRRF_EXTIF) return 2;
    return 3;
}

void Bad_EnterSleep(void) {
    HAL_GPIO_Init(GPIOA, &GPIO_InitStruct);
    HAL_ADC_Start(&hadc1);
    HAL_COMP_Enable(&hcomp1);
    HAL_PWR_ENTER_STOP_MODE();
}

void Good_EnterSleep(void) {
    GPIOA->MODER &= ~GPIO_MODER_MODER5;
    HAL_ADC_Stop(&hadc1);
    HAL_COMP_Disable(&hcomp1);
    HAL_PWR_Set_RANGE_2();
    HAL_PWR_ENTER_STOP();
    HAL_PWR_SET_RANGE_1();
}

