typedef struct PVt PVt;
struct PVt { void (*enter)(void*); void (*exit)(void*); int (*curr)(void*); }

// sleep_strategy.c
void s_enter(void* p) { SCB->SCR &= ~0x4; __WFI(); }
void s_exit(void* p) { SCB->SCR = 0x4; }
int s_curr(void*) { return 1500; }
PVt SVT = {s_enter, s_exit, s_curr};

// main()
PVt* curr = &SVT;
void loop() {
    Mode m = select_mode(batt, empty_q());
    curr->exit(curr);
    curr = get_strategy(m);
